import{_ as p,a0 as o,w as u,s as x,ao as l,I as e,x as n,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"為什麼不要在Linux上只運行開源軟件？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼不要在Linux上只運行開源軟件？ | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼不要在Linux上只運行開源軟件？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼不要在Linux上只運行開源軟件？ | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140607 Got Linux--Add Proprietary Code","title":"為什麼不要在Linux上只運行開源軟件？","tag":"201408","desc":""},"relativePath":"201408/20140607 Got Linux--Add Proprietary Code.md","filePath":"[post].md"}'),s={name:"201408/20140607 Got Linux--Add Proprietary Code.md"};function d(L,i,m,T,f,w){const r=o("Link");return u(),x("div",null,[i[22]||(i[22]=l('<h1 id="為什麼不要在linux上只運行開源軟件" tabindex="-1">為什麼不要在Linux上只運行開源軟件？ <a class="header-anchor" href="#為什麼不要在linux上只運行開源軟件" aria-label="Permalink to “為什麼不要在Linux上只運行開源軟件？”">​</a></h1><p><img src="http://www.linuxinsider.com/images/rw661226/linux-enterprise-proprietary-code.jpg" alt=""></p><blockquote><p>對於一些產業來講，在開源的Linux發行版上運行專屬（proprietary）軟件並不是個例，--相反這很常見。例如，在華爾街，“華爾街上百分之九十九的應用依賴於專屬軟件。在那些運行在Linux上而有專屬許可證的產品中，Oracle是我們非常喜歡的一款”， FSMLabs 的總裁 Victor Yodaiken這樣説。</p></blockquote><p>遷移到Linux平台並不是一個非此即彼的提議。linux作為一個靈活開放的計算平台為用户在軟件選擇上提供了更多的選項。</p><p>第一個方法是Linux的桌面環境，個人計算用户，小型辦公室和企業都可以從眾多的企業級Linux發行版中選擇。在Windows和被限定在其昂貴硬件的基於unix的蘋果OS X之外，Linux桌面系統為用户提供了另外一種零成本或者低成本的選擇。</p><p>另一個遷移的辦法是，讓員工放棄Linux桌面辦公，取而代之，企業可以在Linux服務器上運行後台辦公系統。在網絡應用和雲計算領域遍佈Linux的足跡，Linux服務器能在各種企業設定中尋找到自己的位置。</p><p>第三個方法是運行一個完整的Linux商店，常用的辦公計算、網上瀏覽、圖片編輯工作軟件都存放在開源的軟件包中。開源的資料庫程序連接着後台的軟件和服務器，而且Linux不需要特殊的硬件和多餘的花銷。</p><p>培訓員工使用Linux桌面應用僅需要很少的投入。這要感謝職員們對跨平台軟件的熟悉，例如LibreOffice 和 Open Office, 當然還有 google Chrome和 Firefox瀏覽器。先前的辦公交流工具真的面臨着威脅。</p><p>Linux很靈活。一種新的趨勢是編寫第三方的特定軟件來滿足自己的商業需求，商業軟件公司可以重新編譯打包那些必備的windows或者其他平台的軟件。他們也可以結合開源的組件用他們自己特定的代碼來編寫特定需求的linux應用程序。</p>',9)),e("p",null,[i[1]||(i[1]=n("Dayan Jeremiah，",-1)),t(r,{href:"http://www.icewarp.com/"},{default:a(()=>[...i[0]||(i[0]=[n("Icewarp Pacific",-1)])]),_:1}),i[2]||(i[2]=n("的CEO告訴linuxinsider：“我相信這將是一個新的趨勢，企業正在使用可以運行在Linux系統上的第三方軟件。讓企業走向定製化軟件的一個因素就是購買微軟授權的經濟負擔太重。”",-1))]),i[23]||(i[23]=l('<h3 id="linux-上運行專屬軟件" tabindex="-1">Linux 上運行專屬軟件 <a class="header-anchor" href="#linux-上運行專屬軟件" aria-label="Permalink to “Linux 上運行專屬軟件”">​</a></h3><p>很多公司轉向其他操作系統面臨的問題就是軟件和應用程序的兼容性問題，比如轉向Linux，那麼這家企業必須保證它用的軟件必須是兼容Linux操作系統的，jeremiah補充道。</p><p>Linux操作系統有着數量巨大的軟件，它們運行在數量眾多的linux發行版和桌面環境當中。考慮到行業的特殊性，廣大的開源團體或許並沒有提供替代一個特定計算任務的替代品。這樣的情況下，就不得不花費精力尋找第三方軟件開發者的幫助。</p><p>“通過第三方廠商幫助來保證兼容性的問題，比如，我們可以混合和匹配各種軟件組件在一起，以便讓一個應用程序可以運行在Linux上。”jeremiah這樣説。</p><h3 id="舊貌換新顏" tabindex="-1">舊貌換新顏 <a class="header-anchor" href="#舊貌換新顏" aria-label="Permalink to “舊貌換新顏”">​</a></h3><p>越來越多的專屬軟件公司，比如Icewarp，開發特定的軟件來滿足企業特定的業務需求，他們將許多開源組件混合在一起使用。</p><p>相比在微軟框架下，這樣不僅節約了授權費用，也節省了開發代碼的費用。</p><p>“我們可以使用現成的軟件組件為Linux構建完整的軟件解決方案，這個方案非常節省，高效而且穩定。”jeremiah補充道。</p><p>Icewarp開發的特定軟件並不是免費的開源項目，並不提供免費版本，需要訂購併支付費用，而且售後支持也是收費的。</p><h3 id="代碼移植的混亂" tabindex="-1">代碼移植的混亂 <a class="header-anchor" href="#代碼移植的混亂" aria-label="Permalink to “代碼移植的混亂”">​</a></h3>',10)),e("p",null,[t(r,{href:"https://lucerahq.com"},{default:a(()=>[...i[3]||(i[3]=[n("Lucera",-1)])]),_:1}),i[4]||(i[4]=n("的CEO Jacob Loveless提到，把一個來自其它平台的軟件變成Linux兼容的，一個很大的障礙就是Linux的多樣性。Linux操作系統有一個通用的內核，但是不同的發行版有很多不同的特點。",-1))]),i[24]||(i[24]=l('<p>“當軟件公司不得不在多個Linux系統中交叉編譯時，問題進一步加深。”除了微軟的Exchange資料庫之外（LCTT譯註：此處疑為筆誤，可能是“MS SQL Server”），大部分資料庫都在linux上運行的很好，MySQL和PostSQL是其中非常出名的兩個開源軟件（LCTT譯註：此處PostSQL應該是Postgresql）。”</p><p>在軟件移植到Linux時的最大挑戰，是需要重新編譯代碼，通常你必須要完成一些平台特定的修改才能讓它工作，他説。</p><p>比如，你有特定的基於.Net的代碼或者其他的針對Windows的語言代碼，Linux上開源的編譯器並不總是兼容，所以你有很多的軟件工作必須重做，loveless解釋説。</p><p>另外一個例子就是資料庫，你往往不得不改用其他的資料庫或者不同的網頁服務器。</p><p>“這確實需要一些工作”loveless説道。</p><h3 id="多但不足夠" tabindex="-1">多但不足夠 <a class="header-anchor" href="#多但不足夠" aria-label="Permalink to “多但不足夠”">​</a></h3><p>另外一個轉向Linux的兼容性問題就是公司需要的開源軟件類型。</p><p>“對於公司特定的計算需求開源軟件方案並不完善”ICeWarp的Jeremiah補充説“但是，通常對於Linux來説都是足夠的，開源團體無法做到的特定的應用程序可以由第三方來實現。”</p><p>比如説，IceWarp最近完成的一個特定的Linux兼容的應用程序就不需要採購額外的硬件也沒產生多餘的授權費用。</p><p>這個特定的軟件包含一個負載均衡的集羣，一個運行資料庫的集羣，另外一個是IP服務器的集羣。所有的都運行在RHEL或者CentOS linux發行版當中。</p><h3 id="跟錢走" tabindex="-1">跟錢走！ <a class="header-anchor" href="#跟錢走" aria-label="Permalink to “跟錢走！”">​</a></h3><p>在一些情況下，有錢才有Linux操作系統的應用，有時候Linux服務器在一個領域很流行，又有些時候只是一個特定的Linux桌面應用程序，有時候兩者都有。</p>',12)),e("p",null,[i[6]||(i[6]=n("舉個例子，例如在華爾街，在金融市場中時間同步是關鍵。金融網絡依靠分佈式網絡，用户必須在截止時間內完成交易。其它的應用需要在交易前進行精確的計時。",-1)),t(r,{href:"http://www.fsmlabs.com/"},{default:a(()=>[...i[5]||(i[5]=[n("FSMLabs",-1)])]),_:1}),i[7]||(i[7]=n(" 的總裁 Victor Yodaiken 説，這些功能需要精確的時間同步控制。",-1))]),i[25]||(i[25]=e("p",null,"當FSMLabs開始開發時間同步軟件時，Yodaiken覺得他們只需要開發一個Windows版本。",-1)),i[26]||(i[26]=e("p",null,"然而，事實證明每一個在使用自動交易或者高頻交易的人，甚至以高精度採集數據的人，都運行的是Linux系統，他告訴LinuxInsider。",-1)),i[27]||(i[27]=e("h3",{id:"惜時如金",tabindex:"-1"},[n("惜時如金 "),e("a",{class:"header-anchor",href:"#惜時如金","aria-label":"Permalink to “惜時如金”"},"​")],-1)),i[28]||(i[28]=e("p",null,"FSMLabs在Linux上運行他們的專屬代碼，Linux上的互聯網時間協議（NTP）並不適用於同步時間在納秒級別的應用，比如那些追蹤股票變動，或者交易需求。 windows的不足有另一個原因。",-1)),i[29]||(i[29]=e("p",null,"Yodaiken説道：“（在這方面，）Linux比Windows流行是因為windows沒有一個標準的API可以讓你在毫秒級之下獲取時間，所以Window並不是真的都好，你必須得有特定的API才行。而在Linux下。你不需要在你的應用程序上費力了。”",-1)),e("p",null,[i[9]||(i[9]=n("金融市場是第一個擁抱Linux的，很多早期的系統管理員來自20世紀80年代的",-1)),t(r,{href:"http://www.bell-labs.com/"},{default:a(()=>[...i[8]||(i[8]=[n("貝爾實驗室",-1)])]),_:1}),i[10]||(i[10]=n("，因此這是一個很成熟的市場，他補充到。",-1))]),i[30]||(i[30]=l('<h3 id="滿足需求" tabindex="-1">滿足需求 <a class="header-anchor" href="#滿足需求" aria-label="Permalink to “滿足需求”">​</a></h3><p>在某些領域，在開源的Linux發行版上運行有專利的軟件並不意外，這是很常見的。</p><p>“華爾街99%的應用都運行在有專利的產品上。在我們在Linux上運行的有專屬許可證的產品中，我們很喜歡Oracle。”FSMLab 的 Yodaiken説。</p><p>一些使用Linux的市場需要更多特定的軟件，現有的開源軟件並不能滿足他們，這就是為什麼軟件開發者們為企業Linux應用提供了商業的解決方案。他補充道。</p><p>“這很平常，開源軟件很適合大的市場，這就是為什麼他有廣泛而且通用的需求，不是很多人需要絕對的微秒級的時間，而且如果沒有市場就會發出信號。”他指出。</p><h3 id="linux純粹主義是沒有意義的" tabindex="-1">Linux純粹主義是沒有意義的 <a class="header-anchor" href="#linux純粹主義是沒有意義的" aria-label="Permalink to “Linux純粹主義是沒有意義的”">​</a></h3><p>在Linux上運行完全免費開源的軟件的觀念是欠缺的，有時候你要運行專屬軟件。對於任何特定的行業都是這樣。</p><p>當一個專業的計算不需要進入廣泛市場時，第三方的軟件開發者可以提供特定的，商業的或者閉源的軟件解決方案。由於商業需求不斷進入Linux系統，絕對的開源將成為過去的事情。</p><p>“在Linux上擁有商業軟件是相當普遍的”，Yodaiken説，“商人都不是純粹主義者，他們只想解決問題。”</p><p>Jack M.Genmain從Apple II和PC時代就開始報道電腦科技，他還有原始的IBM PC-Jr和運行DOS的機器。他留着共享軟件和開源軟件的linux桌面。他運行着好幾種版本的Windows和Linux，經常不能決定是用他的tablet還是netbook還是android智能機，而不是用他的桌面電腦或者筆記本。你可以在google+上聯繫他。</p><hr>',11)),e("p",null,[i[12]||(i[12]=n("via: ",-1)),t(r,{href:"http://www.linuxinsider.com/story/80555.html"},{default:a(()=>[...i[11]||(i[11]=[n("http://www.linuxinsider.com/story/80555.html",-1)])]),_:1})]),e("p",null,[i[15]||(i[15]=n("作者：Jack M. Germain 譯者：",-1)),t(r,{href:"https://github.com/jiajia9linuxer"},{default:a(()=>[...i[13]||(i[13]=[n("jiajia9linuxer",-1)])]),_:1}),i[16]||(i[16]=n(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:a(()=>[...i[14]||(i[14]=[n("wxy",-1)])]),_:1})]),e("p",null,[i[19]||(i[19]=n("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[17]||(i[17]=[n("LCTT",-1)])]),_:1}),i[20]||(i[20]=n(" 原創翻譯，",-1)),t(r,{href:"http://linux.cn/"},{default:a(()=>[...i[18]||(i[18]=[n("Linux中國",-1)])]),_:1}),i[21]||(i[21]=n(" 榮譽推出",-1))])])}const S=p(s,[["render",d]]);export{P as __pageData,S as default};
